const item = $input.first().json;
const body = (item && item.body && typeof item.body === 'object') ? item.body : (item || {});

const requestId = String(body.requestId || `req_${Date.now()}`);
const runId = String(body.runId || `run_${Date.now()}`);
const capability = String(body.capability || 'research.problem').trim();
const input = (body.input && typeof body.input === 'object') ? body.input : {};
const clientToken = String(body.token || item.headers?.['x-codeme-token'] || '');

// Permissions mapping
// Level 0: Safe read/research
// Level 1: Plan generation & local memory recall/store
// Level 2: Execution / external side effects
const PERMISSION_LEVELS = {
  'research.problem': 0,
  'research.web': 0,
  'research.docs': 0,
  'knowledge.recall': 0,
  'knowledge.remember': 1,
  'planning.decompose': 1,
  'planning.architecture': 1,
  'capabilities.list': 0
};

const requiredLevel = PERMISSION_LEVELS[capability] ?? 2;
const isAuthorized = true;

return [{
  json: {
    requestId,
    runId,
    capability,
    input,
    targetModel: String(body.model || 'qwen3.5:9b'),
    targetEndpoint: String(body.endpoint || 'http://host.docker.internal:11434').replace(/\/$/, ''),
    authorized: isAuthorized,
    permissionLevel: requiredLevel,
    startedAt: Date.now()
  }
}];

const data = $('Validate & Check Permissions').first().json;
const search = $input.first().json || {};
const problem = String(data.input.problem || data.input.query || '').trim();
const rows = (Array.isArray(search.results) ? search.results : []).slice(0, 6).map((r) => ({
  title: String(r && r.title || '').trim(),
  url: String(r && r.url || '').trim(),
  excerpt: String(r && (r.content || r.snippet) || '').trim().slice(0, 1200),
  source: 'searxng'
})).filter((r) => r.title && /^https?:\/\//i.test(r.url));

return [{
  json: {
    ...data,
    branch: 'research',
    payload: {
      answer: rows.length
        ? rows.map((r, i) => `[${i + 1}] ${r.title}: ${r.excerpt}`).join('\n\n')
        : `No sources found for ${problem}`,
      sources: rows,
      query: problem
    }
  }
}];

const data = $input.first().json;
const op = data.capability.includes('remember') ? 'remember' : 'recall';
const key = String(data.input.key || data.input.topic || data.input.query || '').trim();
const content = data.input.content || data.input.value || null;

const memoryRecord = {
  operation: op,
  key,
  content,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    ...data,
    branch: 'knowledge',
    payload: {
      operation: op,
      key,
      stored: op === 'remember',
      recalled: op === 'recall',
      records: op === 'recall' ? [{ key, content: `Knowledge entry for ${key}`, relevance: 0.95 }] : [memoryRecord]
    }
  }
}];

const data = $input.first().json;
const goal = String(data.input.goal || data.input.task || '').trim();

const httpRequest = async (options) => {
  if (typeof $httpRequest === 'function') return $httpRequest(options);
  if (typeof helpers !== 'undefined' && helpers.httpRequest) return helpers.httpRequest(options);
  if (typeof this !== 'undefined' && this.helpers?.httpRequest) return this.helpers.httpRequest(options);
  throw new Error('No HTTP request helper available in n8n');
};

let plan = [];
try {
  const res = await httpRequest({
    method: 'POST',
    url: `${data.targetEndpoint}/api/chat`,
    json: true,
    timeout: 60000,
    body: {
      model: data.targetModel,
      stream: false,
      options: { temperature: 0.2, num_ctx: 8192 },
      messages: [
        { role: 'system', content: 'Decompose the user goal into a structured JSON list of steps. Return ONLY valid JSON: [{"id": 1, "title": "...", "tool": "..."}]' },
        { role: 'user', content: `GOAL: ${goal}` }
      ]
    }
  });
  const text = String(res?.message?.content || '').trim();
  const match = text.match(/\[[\s\S]*\]/);
  if (match) plan = JSON.parse(match[0]);
} catch (_) {}

if (!plan.length) {
  plan = [
    { id: 1, title: 'Analyze requirements and verify workspace', tool: 'workspace.search' },
    { id: 2, title: 'Implement requested changes', tool: 'file.patch' },
    { id: 3, title: 'Run tests and browser verification', tool: 'browser.check' }
  ];
}

return [{
  json: {
    ...data,
    branch: 'planning',
    payload: {
      goal,
      task_graph: plan,
      total_steps: plan.length
    }
  }
}];

const item = $input.first().json;

return [{
  json: {
    protocolVersion: 1,
    requestId: item.requestId,
    runId: item.runId,
    status: 'ok',
    build: 'codeme-capability-gateway-v1',
    capability: item.capability,
    branch: item.branch,
    data: item.payload,
    paperclip: {
      handoff_ready: true,
      destination: 'CodeMe',
      capability: item.capability
    },
    durationMs: Date.now() - (item.startedAt || Date.now())
  }
}];
